fn hash(seed: i32) -> i32 {
    let mut h: i32 = seed * 747796405 + 2891336453;
    h = (h >> 16) ^ h;
    if h < 0 { h = 0 - h; }
    h
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(1, w / 2);
        host::display::state_set(2, 0);
    }
    let down: i32 = host::display::pointer_down();
    let tap: bool = down == 1 && host::display::state_get(5) == 0;
    host::display::state_set(5, down);
    let phase: i32 = host::display::state_get(2);
    if phase != 0 {
        if phase == 1 {
            host::display::clear(0x041804);
            host::display::draw_string(120, 190, "YOU HAULED IT IN", 0x00ff88, 3);
        } else {
            host::display::clear(0x180404);
            host::display::draw_string(110, 190, "DRAGGED THROUGH", 0xff4040, 3);
        }
        host::display::draw_number(190, 250, host::display::state_get(3), 0x00ff88, 4);
        host::display::draw_number(290, 250, host::display::state_get(4), 0xff4040, 4);
        host::display::draw_string(130, 330, "TAP FOR ROUND", 0x808080, 2);
        host::display::draw_number(400, 330, host::display::state_get(6) + 2, 0x808080, 2);
        if tap {
            host::display::state_set(6, host::display::state_get(6) + 1);
            host::display::state_set(1, w / 2);
            host::display::state_set(2, 0);
        }
    } else {
        let mut x: i32 = host::display::state_get(1);
        let round: i32 = host::display::state_get(6);
        if tap { x = x + 14; }
        x = x - 1;
        if hash(t / 60 + round * 99) % 3 == 0 { x = x - 1; }
        if x <= 60 {
            host::display::state_set(2, 2);
            host::display::state_set(4, host::display::state_get(4) + 1);
        }
        if x >= w - 60 {
            host::display::state_set(2, 1);
            host::display::state_set(3, host::display::state_get(3) + 1);
        }
        host::display::state_set(1, x);
        host::display::clear(0x101418);
        host::display::fill_rect(0, 0, 60, h, 0x301010);
        host::display::fill_rect(w - 60, 0, 60, h, 0x103014);
        host::display::fill_rect(60, h / 2 - 3, w - 120, 6, 0x6a5030);
        host::display::fill_rect(w / 2 - 1, h / 2 - 30, 2, 60, 0x404040);
        host::display::fill_rect(x - 8, h / 2 - 16, 16, 32, 0xffcc44);
        host::display::draw_string(110, 80, "TAP FAST TO PULL RIGHT", 0xffffff, 2);
        host::display::draw_string(70, h - 90, "CPU", 0xff4040, 2);
        host::display::draw_string(w - 130, h - 90, "YOU", 0x00ff88, 2);
        host::display::draw_number(120, 120, host::display::state_get(4), 0xff4040, 2);
        host::display::draw_number(w - 140, 120, host::display::state_get(3), 0x00ff88, 2);
    }
    host::display::present();
}
